#include <bits/stdc++.h>
#define LL long long
#define RANG(i, l, r) for (int i = l; i <= r; i++)
using namespace std;
const int P = 998244353, MOD = 1e9 + 7, B = 1e6;
int normalize_mod(ll d) { return (d % P + P) % P; }
LL total_count, current, prefix_sum[7];
int result;
vector<int> sequences[7];

void build(int level, LL val) {
    total_count++;
    sequences[level].push_back(normalize_mod(total_count - val));
    if (level < 6) RANG(i, 0, 9) build(level + 1, val * 10 + i);
}

int get(int id, int f) {
    int pos = lower_bound(sequences[id].begin(), sequences[id].end(), P - f) - sequences[id].begin();
    return ((LL)f * sequences[id].size() + prefix_sum[id] - (LL)P * (sequences[id].size() - pos)) % MOD;
}

void dfs(int depth, LL v) {
    if (v > total_count) return;
    if (depth >= 1) {
        if (v * B > total_count / 10 && v * B + B - 1 <= total_count) {
            int t = 1;
            RANG(i, 0, 6) (result += get(i, normalize_mod(current - v * t))) %= MOD, t *= 10;
            RANG(i, 0, 6) current += sequences[i].size();
            return;
        }
        result = (result + normalize_mod(++current - v)) % MOD;
    }
    RANG(i, !depth, 9) dfs(depth + 1, v * 10 + i);
}

int main() {
    LL n_input;
    scanf("%lld", &n_input);
    build(0, 0);
    RANG(i, 0, 6) {
        sort(sequences[i].begin(), sequences[i].end());
        for (int j = 0; j < (int)sequences[i].size(); j++) prefix_sum[i] += sequences[i][j];
    }
    current = 0;
    dfs(0, 0);
    printf("%d\n", result);
    return 0;
}
